import java.util.*;

class Solution {
    public int shortestOpenPath(int[][] grid) {
        int n = grid.length;
        if (grid[0][0] == 1 || grid[n - 1][n - 1] == 1) return -1;
        int[][] len = new int[n][n]; // 0 = not visited
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        len[0][0] = 1; // path length counts cells
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            if (x == n - 1 && y == n - 1) return len[x][y];
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++) {
                    int a = x + dx, b = y + dy;
                    if (a >= 0 && b >= 0 && a < n && b < n && grid[a][b] == 0 && len[a][b] == 0) {
                        len[a][b] = len[x][y] + 1;
                        q.add(new int[]{a, b});
                    }
                }
        }
        return -1;
    }
}

