class Solution:
    def shortestOpenPath(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if grid[0][0] or grid[n-1][n-1]: return -1
        d = [[0] * n for _ in range(n)]; d[0][0] = 1; q = deque([(0, 0)])
        while q:
            i, j = q.popleft()
            if (i, j) == (n-1, n-1): return d[i][j]
            for a in (-1, 0, 1):
                for b in (-1, 0, 1):
                    x, y = i + a, j + b
                    if 0 <= x < n and 0 <= y < n and not grid[x][y] and not d[x][y]:
                        d[x][y] = d[i][j] + 1; q.append((x, y))
        return -1

