function shortestOpenPath(grid) {
  const n = grid.length;
  if (grid[0][0] || grid[n-1][n-1]) return -1;
  const d = grid.map(r => r.map(() => 0)); d[0][0] = 1; const q = [[0, 0]];
  for (let h = 0; h < q.length; h++) {
    const [i, j] = q[h];
    if (i === n-1 && j === n-1) return d[i][j];
    for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
      const x = i + a, y = j + b;
      if (x >= 0 && x < n && y >= 0 && y < n && !grid[x][y] && !d[x][y]) { d[x][y] = d[i][j] + 1; q.push([x, y]); }
    }
  }
  return -1;
}
